const listConversations = `-- name: ListConversations :many
SELECT c.id, c.workspace_id, c.channel, c.state, c.subject, c.customer_name, c.customer_email, c.person_id, c.assignee, c.visitor_key, c.ref, c.message_count, c.last_message_at, c.created_at, c.first_reply_at,
       coalesce(left(l.body, 160), '')::text AS preview,
       coalesce(l.direction, '')::text AS last_direction,
       coalesce(l.seq, 0)::int AS last_seq,
       (coalesce(l.seq, 0) > coalesce(r.last_read_seq, 0))::boolean AS unread
FROM conversation c
LEFT JOIN LATERAL (
  SELECT m.body, m.direction, m.seq
  FROM conversation_message m
  WHERE m.workspace_id = c.workspace_id AND m.conversation_id = c.id AND m.direction <> 'note'
  ORDER BY m.seq DESC
  LIMIT 1
) l ON true
LEFT JOIN conversation_read r ON r.workspace_id = c.workspace_id AND r.conversation_id = c.id AND r.user_id = $2::uuid
WHERE c.workspace_id = $1
  AND ($3::text = '' OR c.state = $3)
  AND ($4::boolean = false OR c.assignee = $2::uuid)
  AND ($5::boolean = false OR c.assignee IS NULL)
  AND ($6::text = '' OR c.channel = $6)
  AND ($7::uuid IS NULL OR c.assignee = $7)
  AND ($8::uuid IS NULL OR c.person_id = $8)
  AND (NOT $9::boolean OR coalesce(l.seq, 0) > coalesce(r.last_read_seq, 0))
  AND ($10::text = ''
       OR c.customer_name ILIKE '%' || $10::text || '%'
       OR c.customer_email ILIKE '%' || $10::text || '%'
       OR c.subject ILIKE '%' || $10::text || '%'
       OR l.body ILIKE '%' || $10::text || '%')
  AND ($11::timestamptz IS NULL OR (c.last_message_at, c.id) < ($11::timestamptz, $12::uuid))
ORDER BY c.last_message_at DESC, c.id DESC
LIMIT $13::int
`

type ListConversationsParams struct {
	WorkspaceID uuid.UUID
	Me          uuid.UUID
	State       string
	Mine        bool
	Unassigned  bool
	Channel     string
	AssigneeID  uuid.NullUUID
	PersonID    uuid.NullUUID
	UnreadOnly  bool
	Search      string
	AfterAt     pgtype.Timestamptz
	AfterID     uuid.NullUUID
	PageSize    int32
}

type ListConversationsRow struct {
	ID            uuid.UUID
	WorkspaceID   uuid.UUID
	Channel       string
	State         string
	Subject       string
	CustomerName  string
	CustomerEmail pgtype.Text
	PersonID      uuid.NullUUID
	Assignee      uuid.NullUUID
	VisitorKey    pgtype.Text
	Ref           string
	MessageCount  int32
	LastMessageAt time.Time
	CreatedAt     time.Time
	FirstReplyAt  pgtype.Timestamptz
	Preview       string
	LastDirection string
	LastSeq       int32
	Unread        bool
}

// The newest non-note message gives the row preview, whether the last word was
// the customer's, and whether this person has seen it yet.
func (q *Queries) ListConversations(ctx context.Context, arg ListConversationsParams) ([]ListConversationsRow, error) {
	rows, err := q.db.Query(ctx, listConversations,
		arg.WorkspaceID,
		arg.Me,
		arg.State,
		arg.Mine,
		arg.Unassigned,
		arg.Channel,
		arg.AssigneeID,
		arg.PersonID,
		arg.UnreadOnly,
		arg.Search,
		arg.AfterAt,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListConversationsRow
	for rows.Next() {
		var i ListConversationsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Channel,
			&i.State,
			&i.Subject,
			&i.CustomerName,
			&i.CustomerEmail,
			&i.PersonID,
			&i.Assignee,
			&i.VisitorKey,
			&i.Ref,
			&i.MessageCount,
			&i.LastMessageAt,
			&i.CreatedAt,
			&i.FirstReplyAt,
			&i.Preview,
			&i.LastDirection,
			&i.LastSeq,
			&i.Unread,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

