const upsertInboxSetting = `-- name: UpsertInboxSetting :one
INSERT INTO inbox_setting (workspace_id, chat_enabled, email_enabled, origins, greeting, widget_epoch, inbound_epoch)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (workspace_id) DO UPDATE SET chat_enabled = EXCLUDED.chat_enabled, email_enabled = EXCLUDED.email_enabled, origins = EXCLUDED.origins,
  greeting = EXCLUDED.greeting, widget_epoch = EXCLUDED.widget_epoch, inbound_epoch = EXCLUDED.inbound_epoch, updated_at = now()
RETURNING workspace_id, chat_enabled, email_enabled, origins, greeting, widget_epoch, inbound_epoch, updated_at, reply_target_hours
`

type UpsertInboxSettingParams struct {
	WorkspaceID  uuid.UUID
	ChatEnabled  bool
	EmailEnabled bool
	Origins      []string
	Greeting     string
	WidgetEpoch  int32
	InboundEpoch int32
}

func (q *Queries) UpsertInboxSetting(ctx context.Context, arg UpsertInboxSettingParams) (InboxSetting, error) {
	row := q.db.QueryRow(ctx, upsertInboxSetting,
		arg.WorkspaceID,
		arg.ChatEnabled,
		arg.EmailEnabled,
		arg.Origins,
		arg.Greeting,
		arg.WidgetEpoch,
		arg.InboundEpoch,
	)
	var i InboxSetting
	err := row.Scan(
		&i.WorkspaceID,
		&i.ChatEnabled,
		&i.EmailEnabled,
		&i.Origins,
		&i.Greeting,
		&i.WidgetEpoch,
		&i.InboundEpoch,
		&i.UpdatedAt,
		&i.ReplyTargetHours,
	)
	return i, err
}
